import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flag):
    return {"id": id_, "day": day, "flagged": flag}


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 2, None)]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 2, False)] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"c": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days,total", [(0, 0), (2, 5), (4, 6)])
def test_flags_in_window(days, total):
    assert flags_in_window([1, 2, 3], days) == total


def test_parse_skips_comments_and_blank_lines_and_trims_fields():
    lines = ["", " \t", "  # comment", " a , -1 , 1 ", "b,0, 0", "c, 2, "]
    assert parse_transcript_log(lines) == [
        event("a", -1, True), event("b", 0, False), event("c", 2, None)
    ]


@pytest.mark.parametrize("bad", ["a,1", "b,1,0,extra", "a,not-an-int,1"])
def test_parse_errors_identify_original_line(bad):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["# skip", "ok,0,", " ", bad])


def test_dedupe_keeps_last_occurrence_and_sorts_survivors():
    old, new = event("b", 9, False), event("b", 1, True)
    a, c = event("a", 1, None), event("c", 0, True)
    assert dedupe_transcripts([old, new, c, a]) == [c, a, new]


def test_daily_counts_include_empty_days_and_ignore_outside_range():
    events = [event(str(d), d, True) for d in [0, 2, 2, 4, 6]] + [event("n", 3, None)]
    assert daily_flag_counts(events, 1, 5) == [0, 2, 0, 1, 0]
    assert daily_flag_counts(events, 4, 4) == [1]
    assert daily_flag_counts(events, 5, 4) == []


def test_summary_uses_calendar_window_and_pooled_rate():
    groups = {"a": [event("a", 1, True)], "b": [event("b", 4, False), event("c", 4, None)], "c": []}
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary({"a": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_ranking_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "a": [event("a", 1, True)],
              "b": [event("b", 1, False)], "empty": []}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 10) == ["a", "z", "b"]


def test_group_rates_in_name_order():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


@pytest.mark.parametrize("counts,length", [([], 0), ([0, -1], 0), ([1, 2, 0, 1, -1, 3], 2)])
def test_longest_streak_requires_consecutive_positive_counts(counts, length):
    assert longest_flag_streak(counts) == length
